from __future__ import annotations

import re
from dataclasses import dataclass


@dataclass(frozen=True)
class Ref:
    col: int
    row: int
    abs_col: bool = False
    abs_row: bool = False

__all__ = ["parse_ref", "parse_range", "to_a1"]

MAX_COL = 701  # ZZ, 0-based
MAX_ROW = 9998  # 9999, 0-based

_REF_RE = re.compile(r"(\$?)([A-Za-z]{1,2})(\$?)([1-9][0-9]{0,3})")


def parse_ref(s: str) -> Ref:
    m = _REF_RE.fullmatch(s)
    if m is None:
        raise ValueError(f"invalid cell reference: {s!r}")
    abs_col, letters, abs_row, digits = m.groups()
    n = 0
    for ch in letters.upper():
        n = n * 26 + (ord(ch) - 64)
    return Ref(n - 1, int(digits) - 1, abs_col == "$", abs_row == "$")


def parse_range(s: str) -> tuple[Ref, Ref]:
    parts = s.split(":")
    if len(parts) != 2:
        raise ValueError(f"invalid range: {s!r}")
    a = parse_ref(parts[0])
    b = parse_ref(parts[1])
    # Each axis takes its min/max from the corner supplying it; tie -> first corner.
    if b.col < a.col:
        left, right = b, a
    else:
        left, right = a, b
    if b.row < a.row:
        top, bottom = b, a
    else:
        top, bottom = a, b
    return (
        Ref(left.col, top.row, left.abs_col, top.abs_row),
        Ref(right.col, bottom.row, right.abs_col, bottom.abs_row),
    )


def to_a1(ref: Ref) -> str:
    if not (0 <= ref.col <= MAX_COL and 0 <= ref.row <= MAX_ROW):
        raise ValueError(f"reference out of range: {ref!r}")
    letters = ""
    n = ref.col + 1
    while n:
        n, r = divmod(n - 1, 26)
        letters = chr(65 + r) + letters
    return (
        ("$" if ref.abs_col else "")
        + letters
        + ("$" if ref.abs_row else "")
        + str(ref.row + 1)
    )

